from playwright.sync_api import sync_playwright
import json

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": 1920, "height": 930})
    pg.goto(URL)
    pg.wait_for_timeout(400)
    ch = pg.evaluate("""() => {
      const el = document.querySelector('.process-chapter');
      const r = el.getBoundingClientRect();
      return {top: r.top + window.scrollY, height: el.offsetHeight, vh: window.innerHeight};
    }""")
    print("chapter:", ch)
    y0 = ch['top'] + 0.20 * (ch['height'] + ch['vh']) - ch['vh']
    pg.evaluate("(y) => window.scrollTo(0, Math.max(0,y))", y0)
    pg.wait_for_timeout(200)
    pg.mouse.move(960, 465)
    for step in range(20):
        pg.mouse.wheel(0, 200)
        pg.wait_for_timeout(120)
        r = pg.evaluate("""() => {
          const plane = document.querySelector('.tes-plane');
          const cs = getComputedStyle(plane);
          const rect = plane.getBoundingClientRect();
          const clipB = parseFloat(cs.getPropertyValue('--fz-clip-b'))||0;
          const bottom = rect.top + rect.height - clipB;
          const els = document.elementsFromPoint(rect.left+50, bottom-3).map(e=>e.tagName+'.'+e.className).slice(0,4);
          const elsTop = document.elementsFromPoint(rect.left+50, rect.top+3).map(e=>e.tagName+'.'+e.className).slice(0,4);
          return {
            frozen: plane.hasAttribute('data-frozen'), gone: plane.hasAttribute('data-gone'),
            top: rect.top, bottom, left: rect.left, right: rect.left+rect.width,
            scrollY: window.scrollY,
            elsAtBottomEdge: els, elsAtTopEdge: elsTop,
          };
        }""")
        print(step, json.dumps(r))
    b.close()

