from playwright.sync_api import sync_playwright
import json

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    pg = b.new_page(viewport={"width": 1920, "height": 930})
    pg.goto(URL)
    pg.wait_for_timeout(400)
    ch = pg.evaluate("""() => {
      const el = document.querySelector('.process-chapter');
      const r = el.getBoundingClientRect();
      return {top: r.top + window.scrollY, height: el.offsetHeight, vh: window.innerHeight};
    }""")
    y0 = ch['top'] + 0.20 * (ch['height'] + ch['vh']) - ch['vh']
    pg.evaluate("(y) => window.scrollTo(0, Math.max(0,y))", y0)
    pg.wait_for_timeout(200)
    pg.mouse.move(960, 465)
    for step in range(20):
        pg.mouse.wheel(0, 200)
        pg.wait_for_timeout(120)
        r = pg.evaluate("""() => {
          const plane = document.querySelector('.tes-plane');
          if (!plane.hasAttribute('data-frozen')) return {skip:true, scrollY: window.scrollY};
          const cs = getComputedStyle(plane);
          const rect = plane.getBoundingClientRect();
          const clipB = parseFloat(cs.getPropertyValue('--fz-clip-b'))||0;
          const top = rect.top, bottom = rect.top + rect.height - clipB;
          const left = rect.left, right = rect.left + rect.width;
          // walk the 4 edges at several points, find text nodes hidden BEHIND tes-plane
          function textAt(x,y){
            const stack = document.elementsFromPoint(x,y);
            const idx = stack.findIndex(e => e.classList && e.classList.contains('tes-plane'));
            if (idx === -1) return null; // plane not painted here at all
            // is there a text-bearing element ABOVE (before) plane in the stack?
            const above = stack.slice(0, idx);
            const covered = above.some(e => e.tagName === 'P' || e.tagName === 'H3' || (e.className && String(e.className).includes('step-band')));
            // any text-bearing element BELOW (after) plane that would be hidden?
            const below = stack.slice(idx+1);
            const hidden = below.filter(e => e.tagName === 'P' || e.tagName === 'H3');
            return {idx, coveredByText: covered, hiddenTextBehind: hidden.map(e=>e.tagName+':'+ (e.textContent||'').slice(0,20))};
          }
          const pts = [];
          for (let frac = 0; frac <= 1; frac += 0.25){
            pts.push(['top', left + frac*(right-left), top+1]);
            pts.push(['bottom', left + frac*(right-left), bottom-1]);
          }
          for (let frac = 0; frac <= 1; frac += 0.33){
            pts.push(['left', left+1, top + frac*(bottom-top)]);
            pts.push(['right', right-1, top + frac*(bottom-top)]);
          }
          const findings = [];
          for (const [edge,x,y] of pts){
            const t = textAt(x,y);
            if (t && t.hiddenTextBehind.length){
              findings.push({edge, x: Math.round(x), y: Math.round(y), ...t});
            }
          }
          return {scrollY: window.scrollY, top, bottom, left, right, findings};
        }""")
        print(step, json.dumps(r))
    b.close()

