/* PLAN 063 (Lead r19, kontinuiteten blått->ritning). Rubrikens EGEN
   underkant (live, samma yta latchTick redan läser för CASES nedan)
   jämförs mot --band-h: när den passerar är konturarket redan
   osynligt ovanför skärmen (uppmätt, measure_visible_ark.py: arkets
   underkant -48px vid samma scrollläge titelns underkant korsar
   band-h) - bytet till position:fixed syns aldrig, bara att arket
   "landar om" en gång till på RÄTT ställe (--fz-t/l/w/h, samma tal
   som .process-stick pinnar vid). data-gone tonar bort det frysta
   arket när griden faktiskt syns. chAct.cur < .30 (under
   landningströskeln .36, med marginal) återställer båda om
   besökaren skrollar tillbaka upp. */
if (processChapterEl && tesPlaneEl && processTitleEl){
  var chAct = findAct(acts, processChapterEl);
  if (!chAct || isNaN(chAct.cur)){
    again = true;
  } else {
    if (!planeFrozen && processTitleEl.getBoundingClientRect().bottom <= planeBandH){
      planeFrozen = true;
      tesPlaneEl.toggleAttribute('data-frozen', true);
    }

