from playwright.sync_api import sync_playwright
import json, sys

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

CHECK_JS = """
() => {
  const plane = document.querySelector('.tes-plane');
  if (!plane.hasAttribute('data-frozen')) return {frozen:false};
  const cs = getComputedStyle(plane);
  const rect = plane.getBoundingClientRect();
  const clipB = parseFloat(cs.getPropertyValue('--fz-clip-b'))||0;
  const top = rect.top, bottom = rect.top + rect.height - clipB;
  const left = rect.left, right = rect.left + rect.width;
  if (bottom <= top) return {frozen:true, empty:true};
  function isOpaque(el){
    const c = getComputedStyle(el).backgroundColor;
    const m = /rgba?\\(([^)]+)\\)/.exec(c);
    if (!m) return false;
    const parts = m[1].split(',').map(s=>parseFloat(s));
    const a = parts.length > 3 ? parts[3] : 1;
    return a >= 0.98;
  }
  function hasOwnText(el){
    if (!(el.tagName === 'P' || el.tagName === 'H3' || el.tagName === 'H2' || el.tagName === 'SPAN' || el.tagName === 'A')) return false;
    for (const n of el.childNodes){
      if (n.nodeType === 3 && n.textContent.trim().length) return true;
    }
    return false;
  }
  function checkPoint(edge, x, y){
    const stack = document.elementsFromPoint(x, y);
    const idx = stack.findIndex(e => e.classList && e.classList.contains('tes-plane'));
    if (idx === -1) return null;
    for (let i = idx+1; i < stack.length; i++){
      const el = stack[i];
      if (hasOwnText(el)) return {edge, x: Math.round(x), y: Math.round(y), text: el.tagName+':'+el.textContent.trim().slice(0,30)};
      if (isOpaque(el)) return null; // opaque cover found before reaching text - safe
    }
    return null;
  }
  const findings = [];
  const N = 12;
  for (let i = 0; i <= N; i++){
    const x = left + (right-left)*i/N;
    let f = checkPoint('top', x, top+1); if (f) findings.push(f);
    f = checkPoint('bottom', x, bottom-1); if (f) findings.push(f);
  }
  for (let i = 0; i <= N; i++){
    const y = top + (bottom-top)*i/N;
    let f = checkPoint('left', left+1, y); if (f) findings.push(f);
    f = checkPoint('right', right-1, y); if (f) findings.push(f);
  }
  return {frozen:true, gone: plane.hasAttribute('data-gone'), top, bottom, left, right, findings};
}
"""

def run(w, h):
    with sync_playwright() as p:
        b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
        pg = b.new_page(viewport={"width": w, "height": h})
        pg.goto(URL)
        pg.wait_for_timeout(300)
        ch = pg.evaluate("""() => {
          const el = document.querySelector('.process-chapter');
          const r = el.getBoundingClientRect();
          return {top: r.top + window.scrollY, height: el.offsetHeight, vh: window.innerHeight};
        }""")
        # find the scrollY where data-gone first becomes true (coarse binary-ish scan)
        lo = ch['top'] - ch['vh']
        hi = ch['top'] + ch['height'] + ch['vh']
        gone_y = None
        y = lo
        while y <= hi:
            pg.evaluate("(y) => window.scrollTo(0, Math.max(0,y))", y)
            pg.wait_for_timeout(15)
            r = pg.evaluate("document.querySelector('.tes-plane').hasAttribute('data-gone')")
            if r:
                gone_y = y
                break
            y += 50
        if gone_y is None:
            gone_y = hi
        start = max(0, gone_y - 1000)
        end = gone_y + 1000
        all_findings = []
        y = start
        frames = 0
        while y <= end:
            pg.evaluate("(y) => window.scrollTo(0, Math.max(0,y))", y)
            pg.wait_for_timeout(15)
            r = pg.evaluate(CHECK_JS)
            frames += 1
            if r.get("findings"):
                for f in r["findings"]:
                    f["scrollY"] = y
                all_findings.extend(r["findings"])
            y += 20
        print(w, "x", h, ": gone_y~=", gone_y, "frames=", frames, "findings=", len(all_findings))
        for f in all_findings[:10]:
            print("  ", f)
        b.close()

for w, h in [(1920,930),(1440,900),(768,1024),(390,844)]:
    run(w, h)
print("done")

